// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 timestamp, uint256 blockNum1, uint256 blockNum2) public {
        timestamp = bound(timestamp, 1, type(uint64).max);
        blockNum1 = bound(blockNum1, 0, type(uint256).max);
        blockNum2 = bound(blockNum2, 0, type(uint256).max);

        vm.assume(blockNum1 % 15 != 0);
        vm.assume(blockNum2 % 15 != 0);

        address sender = makeAddr("sender");
        vm.deal(sender, 20 ether);

        vm.warp(timestamp);
        vm.roll(blockNum1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        vm.warp(timestamp);
        vm.roll(blockNum2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2, "reference C must revert on second call with same timestamp");
    }
}
